#!/usr/bin/env bash
# Remote lifecycle driver — GENERATED by scripts/release/lifecycle-on-device.sh
# (placeholders __PREV_VER__, __CUR_VER__, __TS__ are substituted). Runs on
# the device; writes only /tmp/gn-lc, /home/arduino/gn-data.bak-<ts> and
# package-managed paths. Never prints /etc/game-narrator/env or credentials.
# SC2024 is disabled below: redirects into /tmp/gn-lc are intentional (the
# driver runs unprivileged there; only the commands run as root).
# shellcheck disable=SC2024
set -u

PREV_VER="__PREV_VER__"
CUR_VER="__CUR_VER__"
TS="__TS__"
LC=/tmp/gn-lc
DATA_DIR=/var/lib/game-narrator
DATA_SRC=/home/arduino/gn-data
BACKUP_DIR="/home/arduino/gn-data.bak-${TS}"
ETC_BACKUP="${LC}/etc-backup-${TS}"
API=http://127.0.0.1:8080
SERVICE_USER=game-narrator
BIN=/usr/bin/game-narrator
ACCOUNT=lifecycle-test
SLUG=lifecycle-test

PASS_N=0; FAIL_N=0; SKIP_N=0
pass() { printf 'PASS: %s\n' "$1"; PASS_N=$((PASS_N+1)); }
fail() { printf 'FAIL: %s\n' "$1"; shift || true
         if [ "$#" -gt 0 ]; then printf '%s\n' "$1" | head -12 | sed 's/^/    /'; fi
         FAIL_N=$((FAIL_N+1)); }
skip() { printf 'SKIP: %s (dependency failed)\n' "$1"; SKIP_N=$((SKIP_N+1)); }
note() { printf 'note: %s\n' "$1"; }

# Env-file integrity: mode owner + line count only, never contents.
env_meta() {
  sudo stat -c '%a %U:%G' /etc/game-narrator/env 2>/dev/null
  sudo sh -c 'wc -l < /etc/game-narrator/env' 2>/dev/null
}

installed_version() {
  dpkg -s game-narrator 2>/dev/null | awk '/^Version:/{print $2}'
}

wait_healthy() { # $1 = attempts (2 s apart)
  local _
  for _ in $(seq 1 "$1"); do
    if curl -fsS -m 5 "${API}/api/v1/health/ready" 2>/dev/null | grep -q '"status":"ok"'; then
      return 0
    fi
    sleep 2
  done
  return 1
}

service_active() { [ "$(sudo systemctl is-active game-narrator 2>/dev/null)" = "active" ]; }

restart_service() {
  sudo systemctl daemon-reload
  sudo systemctl enable game-narrator >/dev/null 2>&1
  sudo systemctl start game-narrator
  local _
  for _ in $(seq 1 30); do
    service_active && return 0
    sleep 1
  done
  service_active
}

# doctor with the service env file sourced (never printed): the env file is
# 0600 root, so the sourcing shell must run as root (one sudo, the same
# convention as scripts/hw/run-on-device.sh). Probes run as root (a superset
# of the unit's device permissions). Prints the FAIL check ids, one per
# line (may be empty). Doctor's exit contract: 0 = no FAIL, 1 = FAIL seen,
# 2 = usage error; only rc > 1 is an execution failure here.
doctor_fail_ids() {
  local out rc
  out=$(sudo sh -c 'set -a; . /etc/game-narrator/env; set +a; exec '"$BIN"' doctor --json --data-dir '"$DATA_DIR" 2>/dev/null)
  rc=$?
  [ "$rc" -le 1 ] || return 1
  grep -B3 '"status": "FAIL"' <<<"$out" | grep '"id"' \
    | sed 's/.*"id": *"\([^"]*\)".*/\1/' | sort -u
  return 0
}

api_get_game() {
  local body
  body=$(curl -fsS -m 10 -H "Authorization: Bearer $TOKEN" "${API}/api/v1/games/${SLUG}") || return 1
  grep -q "\"slug\":\"${SLUG}\"" <<<"$body"
}

api_create_game() {
  local resp
  resp=$(curl -fsS -m 15 -X POST "${API}/api/v1/games" \
    -H "Authorization: Bearer $TOKEN" \
    -H "Idempotency-Key: gn-lc-${TS}-$$" \
    -H 'Content-Type: application/json' \
    -d "{\"slug\":\"${SLUG}\",\"title\":\"Lifecycle Test Game\",\"platform\":\"wii\"}") || return 1
  grep -q "\"slug\":\"${SLUG}\"" <<<"$resp"
}

# A test account + fresh operator token so the API steps authenticate.
# TOKEN is kept in a variable; it is never printed.
setup_account() {
  local listing pw
  listing=$(sudo -u "$SERVICE_USER" "$BIN" admin list --data-dir "$DATA_DIR" 2>/dev/null) || return 1
  if ! grep -q "$ACCOUNT" <<<"$listing"; then
    pw=$(tr -dc 'a-zA-Z0-9' </dev/urandom | head -c 24)
    printf '%s' "$pw" | sudo -u "$SERVICE_USER" "$BIN" admin create \
      --username "$ACCOUNT" --role operator --data-dir "$DATA_DIR" >/dev/null 2>&1 || return 1
    note "created test account ${ACCOUNT} (was absent)"
  fi
  TOKEN=$(sudo -u "$SERVICE_USER" "$BIN" admin token --username "$ACCOUNT" \
    --role operator --name lifecycle-test --expires-days 1 --data-dir "$DATA_DIR" \
    2>/dev/null | head -1) || return 1
  [ -n "$TOKEN" ]
}

# Common verification for a running installation: package version, service
# state, /api/v1/health/ready, doctor (no FAILs beyond the baseline),
# env-file integrity, and (when $4=yes) the test game readable.
# Returns 0 on a clean verify.
verify_running() { # $1=step $2=expected version $4=expect game (yes/no)
  local step=$1 want=$2 expect_game=${4:-no}
  local problems=() got now p post_fails
  got=$(installed_version)
  [ "$got" = "$want" ] || problems+=("package version ${got:-none} != ${want}")
  service_active || problems+=("service not active")
  wait_healthy 30 || problems+=("/api/v1/health/ready not ok after 60 s")
  if post_fails=$(doctor_fail_ids); then
    if [ -n "$post_fails" ]; then
      note "${step}: doctor FAILs after transition: [$(tr '\n' ' ' <<<"$post_fails")](baseline: [$(tr '\n' ' ' <<<"$DOCTOR_BASELINE")])"
      if ! no_new_fails <<<"$post_fails"; then
        problems+=("doctor reports a FAIL new since the baseline")
      fi
    else
      note "${step}: doctor 0 FAIL"
    fi
  else
    problems+=("doctor run failed")
  fi
  now=$(env_meta)
  [ "$now" = "$ENV_BEFORE" ] || problems+=("env file metadata changed: ${ENV_BEFORE:-<none>} -> ${now:-<gone>}")
  if [ "$expect_game" = "yes" ]; then
    if [ "$game_ok" = 1 ]; then
      api_get_game || problems+=("test game ${SLUG} not readable after transition")
    else
      note "${step}: skipping game check (game step did not pass)"
    fi
  fi
  if [ "${#problems[@]}" -eq 0 ]; then
    pass "${step} verified (version ${want}, health ok, doctor no new FAIL, env intact)"
    return 0
  fi
  for p in "${problems[@]}"; do fail "${step}: ${p}"; done
  return 1
}

# Restore the database from the pre-flight backup after a clean stop
# (docs/release.md §4.4: the old binary cannot read a too-new schema).
restore_db_from_backup() {
  sudo systemctl stop game-narrator
  local db="$DATA_DIR/game-narrator.sqlite"
  sudo rm -f "$db" "${db}-wal" "${db}-shm"
  sudo cp -a "${BACKUP_DIR}/game-narrator.sqlite" "$db"
  sudo chown "$SERVICE_USER":"$SERVICE_USER" "$db"
  sudo chmod 0640 "$db"
}

ENV_BEFORE=$(env_meta)
ok_backup=0; ok_prev_install=0; ok_prev_run=0; game_ok=0
ok_up=0; ok_rb=0; ok_reup=0; ok_purge=0

# Doctor baseline: the FAIL check ids while the pre-existing build still
# runs. Pre-existing FAILs (device/gateway state) are not packaging
# regressions; a FAIL that appears only after a transition is. M8 asks for
# 0 FAIL — when the baseline is non-empty the deviation is reported with
# this evidence instead of being masked.
if sudo test -x "$BIN"; then
  DOCTOR_BASELINE=$(doctor_fail_ids || true)
  if [ -n "$DOCTOR_BASELINE" ]; then
    echo "doctor baseline (pre-existing FAILs; the set must not grow): [$(tr '\n' ' ' <<<"$DOCTOR_BASELINE")]"
  else
    echo "doctor baseline: 0 FAIL"
  fi
else
  DOCTOR_BASELINE=""
  echo "doctor baseline: n/a (no installed binary — fresh or purged state; the post-install doctor must report 0 FAIL)"
fi

echo "== lifecycle on-device: prev=${PREV_VER} cur=${CUR_VER} (ts ${TS}) =="
echo "installed before: $(installed_version || echo none)"
echo "env file metadata (mode owner / line count): $(env_meta | tr '\n' ' ')"

# ---------------------------------------------------------------- 1 backup
if [ -d "$DATA_SRC" ]; then
  stopped=1
  if sudo systemctl list-unit-files 'game-narrator.service' 2>/dev/null | grep -q 'game-narrator.service'; then
    if ! sudo systemctl stop game-narrator 2>/dev/null; then
      fail "backup: could not stop the service" "$(sudo systemctl status game-narrator 2>&1 | head -10)"
      stopped=0
    fi
  else
    note "backup: game-narrator unit not installed (fresh or purged state); nothing to stop"
  fi
  if [ "$stopped" = 1 ]; then
    if sudo cp -a "$DATA_SRC" "$BACKUP_DIR" \
       && sudo chown -R arduino:arduino "$BACKUP_DIR" \
       && sudo cp -a /etc/game-narrator "$ETC_BACKUP"; then
      src_count=$(sudo find "$DATA_SRC" -type f | wc -l)
      bak_count=$(sudo find "$BACKUP_DIR" -type f | wc -l)
      if [ "$src_count" = "$bak_count" ] && [ "$src_count" -gt 0 ]; then
        pass "backup: ${BACKUP_DIR} (${src_count} files) + ${ETC_BACKUP}"
        ok_backup=1
      else
        fail "backup: file count mismatch src=${src_count} bak=${bak_count}"
      fi
    else
      fail "backup: copy failed" "$(sudo ls -la "$BACKUP_DIR" 2>&1)"
    fi
  fi
else
  fail "backup: data source $DATA_SRC missing"
fi

# ---------------------------------------------------------------- 2 install previous
# Plain install, no --allow-downgrades: snapshot versions are monotonic in
# the commit (ADR 0060), so replacing an older dirty build with prev is an
# ordinary upgrade. Only the deliberate rollback (step 6) may move to an
# older version and keeps the flag. If the device happens to run a build
# NEWER than prev, apt's refusal is the correct outcome: the prev/cur pair
# is invalid for this run.
if [ "$ok_backup" = 1 ]; then
  if DEBIAN_FRONTEND=noninteractive sudo apt-get install -y "${LC}/prev.deb" \
       >"${LC}/install-prev.log" 2>&1 \
     && [ "$(installed_version)" = "$PREV_VER" ]; then
    pass "install previous: apt-get installed ${PREV_VER} (replacing the dirty build)"
    ok_prev_install=1
  else
    fail "install previous: apt-get failed or version is $(installed_version || echo none)" \
         "$(tail -8 "${LC}/install-prev.log")"
  fi
else
  skip "install previous"
fi

# ---------------------------------------------------------------- 3 start previous
if [ "$ok_prev_install" = 1 ]; then
  if restart_service && verify_running "install previous" "$PREV_VER" no no; then
    ok_prev_run=1
  fi
else
  skip "start previous"
fi

# ---------------------------------------------------------------- 4 test game on previous
if [ "$ok_prev_run" = 1 ]; then
  if setup_account; then
    if api_get_game; then
      note "test game already present (re-run); reusing it"
      game_ok=1
    elif api_create_game; then
      note "created test game ${SLUG}"
      game_ok=1
    else
      fail "test game: POST /api/v1/games failed"
    fi
  else
    fail "test account: could not create account or mint token"
  fi
  if [ "$game_ok" = 1 ]; then
    # Persistence: a restart must not lose the game.
    if sudo systemctl stop game-narrator && restart_service \
       && wait_healthy 30 && api_get_game; then
      pass "test game persists across a service restart on ${PREV_VER}"
    else
      fail "test game lost across a service restart"
      game_ok=0
    fi
  fi
else
  skip "test game on previous"
fi

# ---------------------------------------------------------------- 5 upgrade to current
if [ "$ok_prev_run" = 1 ]; then
  if DEBIAN_FRONTEND=noninteractive sudo apt-get install -y "${LC}/cur.deb" \
       >"${LC}/upgrade-cur.log" 2>&1 \
     && [ "$(installed_version)" = "$CUR_VER" ]; then
    note "upgrade: prerm drained and stopped the unit (documented policy; started again below)"
  else
    fail "upgrade: apt-get failed or version is $(installed_version || echo none)" \
         "$(tail -8 "${LC}/upgrade-cur.log")"
  fi
  if [ "$(installed_version)" = "$CUR_VER" ] && restart_service \
     && verify_running "upgrade to current" "$CUR_VER" no yes; then
    note "upgrade: data + env preserved, migrations applied when serve opened the store"
    ok_up=1
  fi
else
  skip "upgrade to current"
fi

# ---------------------------------------------------------------- 6 rollback to previous
if [ "$ok_up" = 1 ]; then
  if DEBIAN_FRONTEND=noninteractive sudo apt-get install -y --allow-downgrades "${LC}/prev.deb" \
       >"${LC}/rollback-prev.log" 2>&1 \
     && [ "$(installed_version)" = "$PREV_VER" ]; then
    note "rollback: ${PREV_VER} is an older version (monotonic snapshot versioning, ADR 0060) — reinstalling with --allow-downgrades (docs/release.md §4); only this step may downgrade"
    if restart_service && wait_healthy 30; then
      note "rollback policy outcome: the previous binary starts on the newer data (schema compatible; no DB restore needed)"
      ok_rb=1
    else
      note "rollback policy outcome: previous binary did not come up on the newer data; restoring the DB backup per docs/release.md §4.4"
      if restore_db_from_backup && restart_service; then
        # The pre-flight backup predates the operator token (and, on a fresh
        # device, the test account) that step 4 created this run, so the
        # restore removes those rows and the token the game-read check uses
        # is now invalid (401): re-mint before verifying. On a fresh device
        # the restored data also lacks the mid-run test game; recreate it so
        # the persistence check sees the same fixture the run established.
        if setup_account; then
          api_get_game || api_create_game || true
          ok_rb=1
        else
          fail "rollback: could not re-mint the operator token after the DB restore"
        fi
      else
        fail "rollback: service still down after DB restore" \
             "$(sudo journalctl -u game-narrator -n 15 --no-pager 2>/dev/null)"
      fi
    fi
    if [ "$ok_rb" = 1 ] && ! verify_running "rollback to previous" "$PREV_VER" no yes; then
      ok_rb=0
    fi
  else
    fail "rollback: apt-get downgrade failed or wrong version" "$(tail -8 "${LC}/rollback-prev.log")"
  fi
else
  skip "rollback to previous"
fi

# ---------------------------------------------------------------- 7 re-upgrade to current
if [ "$ok_rb" = 1 ]; then
  if DEBIAN_FRONTEND=noninteractive sudo apt-get install -y "${LC}/cur.deb" \
       >"${LC}/reupgrade-cur.log" 2>&1 \
     && [ "$(installed_version)" = "$CUR_VER" ] \
     && restart_service \
     && verify_running "re-upgrade to current" "$CUR_VER" no yes; then
    ok_reup=1
  else
    fail "re-upgrade to current: failed" "$(tail -8 "${LC}/reupgrade-cur.log")"
  fi
else
  skip "re-upgrade to current"
fi

# ---------------------------------------------------------------- 8 purge + clean install
if [ "$ok_reup" = 1 ]; then
  if sudo dpkg --purge game-narrator >"${LC}/purge.log" 2>&1; then
    problems=()
    dpkg -s game-narrator 2>/dev/null | grep -q '^Status: install ok' && problems+=("package still installed after purge")
    sudo test -x /usr/bin/game-narrator && problems+=("binary survived purge: /usr/bin/game-narrator")
    sudo test -e /etc/game-narrator/config.yaml && problems+=("conffile survived purge: /etc/game-narrator/config.yaml")
    sudo test -f "${DATA_DIR}/game-narrator.sqlite" || problems+=("data dir lost its database on purge")
    sudo getent passwd "$SERVICE_USER" >/dev/null || problems+=("system user gone after purge (docs/release.md §5: kept on purpose)")
    if [ "${#problems[@]}" -eq 0 ]; then
      if sudo test -e /etc/game-narrator/env; then
        note "purge: the admin env file is not package-owned and survived; verified its metadata only"
      else
        note "purge: the admin env file was removed with the config; restoring it from ${ETC_BACKUP}"
        sudo cp -a "${ETC_BACKUP}/env" /etc/game-narrator/env
        sudo chown root:root /etc/game-narrator/env
        sudo chmod 0600 /etc/game-narrator/env
      fi
      pass "purge: package + conffiles removed, data dir + system user kept, env intact"
      ok_purge=1
    else
      for p in "${problems[@]}"; do fail "purge: ${p}"; done
    fi
  else
    fail "purge: dpkg --purge failed" "$(tail -8 "${LC}/purge.log")"
  fi
  if [ "$ok_purge" = 1 ]; then
    if DEBIAN_FRONTEND=noninteractive sudo apt-get install -y "${LC}/cur.deb" \
         >"${LC}/clean-install-cur.log" 2>&1 \
      && [ "$(installed_version)" = "$CUR_VER" ] \
      && restart_service \
      && verify_running "clean install of current" "$CUR_VER" no yes; then
      note "clean install: the pre-purge data (including the test game) survived"
    else
      fail "clean install of current: failed" "$(tail -8 "${LC}/clean-install-cur.log")"
    fi
  fi
else
  skip "purge + clean install"
fi

# ---------------------------------------------------------------- summary
echo "== lifecycle summary: PASS=${PASS_N} FAIL=${FAIL_N} SKIP=${SKIP_N} =="
echo "installed after: $(installed_version || echo none) (want ${CUR_VER})"
echo "env file metadata after: $(env_meta | tr '\n' ' ')"
if [ "$FAIL_N" -eq 0 ] && [ "$(installed_version)" = "$CUR_VER" ] && service_active; then
  echo "lifecycle: OK — device left running ${CUR_VER}"
  exit 0
fi
echo "lifecycle: FAILED — see FAIL lines above"
exit 1
